best = None
for mask in range(1 << m):
    chosen = [edges[i] for i in range(m) if mask >> i & 1]
    cost = sum(e[2] for e in chosen)
    if best is not None and cost >= best:
        continue
    seen = {0}
    changed = True
    while changed:
        changed = False
